 Map<String,Object> basisRequest(long cost,String method,Map<String,Object>body,String key){try{var builder=HttpRequest.newBuilder(URI.create("http://localhost:"+port+"/api/v1/ap/cost-assignments/"+cost)).header("Authorization","Bearer supply-fixture").header("X-Country-Id","101").header("Content-Type","application/json").header("Idempotency-Key",key);builder.method(method,method.equals("GET")?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.write(body)));var response=HttpClient.newHttpClient().send(builder.build(),HttpResponse.BodyHandlers.ofString());var out=json.readMap(response.body());out.put("httpStatus",response.statusCode());return out;}catch(Exception e){throw new RuntimeException(e);}}
