 List<Long> twoNativePartialReceiptsAndConfirmedBills(boolean separateBills){return nativePartialCosts("PCS",2,new BigDecimal("0.005"),List.of(1,1),separateBills?List.of(1,1):List.of(2),false);}
 List<Long> nativePartialCosts(String unit,int ordered,BigDecimal price,List<Integer> receiptQty,List<Integer> billQty,boolean fromOrder){return nativePartialCosts(unit,ordered,price,receiptQty,billQty,fromOrder,"MXN");}
 List<Long> nativePartialCosts(String unit,int ordered,BigDecimal price,List<Integer> receiptQty,List<Integer> billQty,boolean fromOrder,String currency){
  var order=pur.create(c(),"orders",Map.of("entityId",301,"bookId",601,"supplierId",801,"currency",currency,"orderDate",date.toString(),"submit",true,"lines",List.of(Map.of("productId",501,"unit",unit,"qty",ordered,"unitPrice",price))),key());int pieces=receiptQty.stream().mapToInt(Integer::intValue).sum();
  var received=domestic(order,pieces,0,0,true);var exported=export(received,pieces,true);var shipment=shipment(exported,pieces);
  lgs.action(c(),"shipments",id(shipment),"dispatch",Map.of("actualEtd","2026-10-15T00:00:00Z"),key());lgs.action(c(),"shipments",id(shipment),"nodes",Map.of("nodeType","ARRIVED_PORT","actualAt","2026-10-15T01:00:00Z"),key());lgs.action(c(),"shipments",id(shipment),"nodes",Map.of("nodeType","CUSTOMS_RELEASED","actualAt","2026-10-15T02:00:00Z"),key());
  List<Long> costs=new ArrayList<>();for(int quantity:receiptQty){var delivered=lgs.create(c(),"deliveries",Map.of("shipmentId",id(shipment),"bizDate",date.toString(),"dispatch",true,"dispatchedAt","2026-10-15T03:00:00Z","lines",List.of(Map.of("shipmentLineId",id(first(shipment)),"dispatchQty",quantity))),key());var destination=lgs.create(c(),"receipts",Map.of("deliveryId",id(delivered),"bizDate",date.toString(),"lines",List.of(Map.of("deliveryLineId",id(first(delivered)),"goodQty",quantity))),key());lgs.action(c(),"receipts",id(destination),"confirm",Map.of(),key());long cost=owner.queryForObject("SELECT id FROM cst_inbound_cost WHERE source_type='LGS_RECEIPT' AND source_line_id=?",Long.class,id(first(destination)));valuation.confirm(c(),cost,Map.of("bizDate",date.toString()),key());costs.add(cost);}
  for(int quantity:billQty){var created=purchasePayables.createBill(c(),Map.of("billDate",date.toString(),"sources",List.of(Map.of("sourceType",fromOrder?"PUR_ORDER_LINE":"PUR_RECEIPT_LINE","sourceId",id(first(fromOrder?order:received)),"qty",quantity))),key());assertThat(purchasePayables.confirmBill(c(),id(created),Map.of("version",created.get("version")),key()).get("status")).isEqualTo("CONFIRMED");}return costs;
 }
