 void interpretAdjustment(long id){
  long event=owner.queryForObject("SELECT id FROM sys_biz_event WHERE event_type='CST_COST_ADJUSTED' AND source_id=?",Long.class,id);var fact=adjustmentFact(id);var result=postingAccounting.generate(c(),event,key());
  var values=List.of(new BigDecimal(fact.get("postingInventoryAmount").toString()),new BigDecimal(fact.get("postingCogsAmount").toString()),new BigDecimal(fact.get("postingCounterpartAmount").toString()));
  if(values.stream().allMatch(v->v.signum()==0)){assertThat(result.get("status")).isEqualTo("NO_VOUCHER");assertThat(result.get("voucherId")).isNull();assertThat(result.get("reason")).isEqualTo("SOURCE_CONFIRMATION_ZERO_POSTING");}
  else{assertThat(result.get("status")).isEqualTo("GENERATED");long voucher=((Number)result.get("voucherId")).longValue();for(int i=0;i<3;i++){String code=List.of("1405","6401","2241").get(i);BigDecimal balance=owner.queryForObject("SELECT coalesce(sum(l.debit-l.credit),0) FROM fin_voucher_line l JOIN fin_account a ON a.id=l.account_id AND a.country_id=l.country_id WHERE l.voucher_id=? AND a.code=?",BigDecimal.class,voucher,code);assertThat(balance).as(code+" signed original posting").isEqualByComparingTo(i==2?values.get(i).negate():values.get(i));}assertThat(owner.queryForObject("SELECT count(*) FROM fin_voucher_line WHERE voucher_id=?",Integer.class,voucher)).isGreaterThanOrEqualTo(2);}
 }
