  approvals.createRule(c(),Map.of("docType","COST_ADJUSTMENT","name","Finance posting sources","conditions",List.of(),"nodes",List.of(Map.of("nodeName","Finance","approverType","USER","approverRef",201,"mode","ANY"))));
  for(String target:List.of("INVENTORY","COGS"))for(int amount:List.of(2,-1)){var adjustment=valuation.createAdjustment(c(),Map.of("batchId",batch,"amount",amount,"target",target,"reason","Reviewed source difference","bizDate",date.toString()),key());long task=owner.queryForObject("SELECT id FROM wf_task WHERE status='PENDING'",Long.class);approvals.approve(c(),task,"Reviewed");valuation.confirmAdjustment(c(),id(adjustment),Map.of(),key());interpretAdjustment(id(adjustment));}
